LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive.")
    def get_cpu_percent():
        try:
            if platform.system() == 'Windows':
                output = subprocess.check_output('wmic cpu get loadpercentage', shell=True).decode()
                for line in output.strip().split('\n'):
                    line = line.strip()
                    if line and not line.startswith('LoadPercentage'):
                        return float(line)
                return 0.0
            else:
                output = subprocess.check_output(['top', '-bn1']).decode()
                for line in output.split('\n'):
                    if '%Cpu(s)' in line:
                        parts = line.split()
                        for i, part in enumerate(parts):
                            if 'id,' in part:
                                idle = float(part.replace('id,', ''))
                                return 100.0 - idle
                return 0.0
        except Exception:
            return 0.0
    records = []
    start_time = time.time()
    end_time = start_time + duration
    records.append({'timestamp': start_time, 'cpu_percent': get_cpu_percent()})
    next_capture = start_time + interval
    while time.time() < end_time:
        sleep_time = next_capture - time.time()
        if sleep_time > 0:
            time.sleep(sleep_time)
        records.append({'timestamp': time.time(), 'cpu_percent': get_cpu_percent()})
        next_capture += interval
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

