LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    data = []
    start = time.time()
    os_name = platform.system()
    if os_name == 'Windows':
        while True:
            if time.time() - start >= duration:
                break
            time.sleep(interval)
            result = subprocess.run(['wmic', 'cpu', 'get', 'loadpercentage'], capture_output=True, text=True)
            lines = result.stdout.strip().splitlines()
            cpu = None
            for line in lines:
                line = line.strip()
                if line.isdigit():
                    cpu = int(line)
                    break
            if cpu is not None:
                data.append({"timestamp": time.time(), "cpu_percent": cpu})
    else:
        def read_proc_stat():
            with open('/proc/stat', 'r') as f:
                for line in f:
                    if line.startswith('cpu '):
                        parts = line.split()
                        total = sum(int(x) for x in parts[1:])
                        idle = int(parts[4])
                        return total, idle
        prev_total, prev_idle = read_proc_stat()
        while True:
            if time.time() - start >= duration:
                break
            time.sleep(interval)
            cur_total, cur_idle = read_proc_stat()
            delta_total = cur_total - prev_total
            delta_idle = cur_idle - prev_idle
            if delta_total > 0:
                cpu_percent = 100.0 * (1 - delta_idle / delta_total)
            else:
                cpu_percent = 0.0
            data.append({"timestamp": time.time(), "cpu_percent": cpu_percent})
            prev_total, prev_idle = cur_total, cur_idle
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

