import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError(f"Commands file not found: {commands_file_path}")
    os.makedirs(output_dir_path, exist_ok=True)
    results = []
    with open(commands_file_path, newline='') as csvfile:
        reader = csv.reader(csvfile)
        for index, row in enumerate(reader):
            if not row:
                continue
            command = row[0].strip()
            if not command:
                continue
            output_file = os.path.join(output_dir_path, f'command_{index}_output.txt')
            try:
                proc = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                if proc.returncode == 0:
                    with open(output_file, 'w') as f:
                        f.write(proc.stdout)
                else:
                    with open(output_file, 'w') as f:
                        f.write(f"Command failed with exit code {proc.returncode}\n{proc.stderr}")
            except Exception as e:
                with open(output_file, 'w') as f:
                    f.write(f"Command execution error: {e}\n")
            results.append(output_file)
    return results

