def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path):
        raise OSError("script_path does not exist")

    proc = subprocess.Popen(script_path, shell=True)
    start_time = time.time()
    timeout_end = start_time + timeout

    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    cpu_start = sum(p.cpu_times()[:2])
    prev_rss = 0
    mem_accum = 0
    process_alive = True

    while process_alive and time.time() < timeout_end:
        ret = proc.poll()
        if ret is not None:
            process_alive = False
            break
        try:
            mem_info = p.memory_info()
            rss = mem_info.rss
            if rss > prev_rss:
                mem_accum += (rss - prev_rss)
            prev_rss = rss
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        time.sleep(0.1)

    if process_alive:
        p.terminate()
        time.sleep(0.5)
        try:
            p.wait(timeout=0.5)
        except psutil.TimeoutExpired:
            p.kill()
        process_alive = False

    elapsed = time.time() - start_time
    if elapsed == 0:
        cpu_percent = 0.0
    else:
        try:
            cpu_end = sum(p.cpu_times()[:2])
        except (psutil.NoSuchProcess, AttributeError):
            cpu_end = cpu_start
        cpu_percent = ((cpu_end - cpu_start) / elapsed) * 100.0

    return {'CPU Usage': cpu_percent, 'Memory Usage': mem_accum}

